mapper.select:
SELECT audit.occurred_at AS occurredAt, audit.operator_user_id AS operatorUserId, audit.operator_type AS operatorType, audit.action_type AS actionType, audit.resource_type AS resourceType, audit.resource_id AS resourceId, audit.result_status AS resultStatus, audit.reason, audit.request_id AS requestId, audit.error_code AS errorCode, audit.network_address AS networkAddress, audit.before_data AS beforeData, audit.after_data AS afterData FROM audit_log audit WHERE 1=1
AND audit.occurred_at >= #{filters.occurredFrom}
AND audit.occurred_at < #{filters.occurredTo}
AND audit.operator_user_id=#{filters.operatorId}
AND audit.operator_type=#{filters.operatorRole}
AND audit.action_type LIKE CONCAT(#{filters.module}, '%')
AND audit.action_type=#{filters.actionType}
AND audit.resource_type=#{filters.targetType}
AND audit.resource_id=#{filters.targetId}
AND audit.result_status=
'SUCCESS' 'FAILED'
AND audit.error_code=#{filters.errorCode}
AND audit.request_id=#{filters.requestId}
AND audit.network_address=#{filters.networkAddress}
AND (audit.action_type LIKE CONCAT('%',#{filters.keyword},'%') OR audit.resource_type LIKE CONCAT('%',#{filters.keyword},'%') OR audit.resource_id LIKE CONCAT('%',#{filters.keyword},'%') OR audit.reason LIKE CONCAT('%',#{filters.keyword},'%'))
ORDER BY audit.occurred_at DESC, audit.id DESC LIMIT 10000

SELECT batch.id AS batchId, batch.batch_code AS batchCode, batch.batch_name AS batchName, YEAR(batch.start_at) AS academicYear, snapshot.metric_version AS metricVersion, snapshot.metrics_json AS metricsJson, snapshot.dimensions_json AS dimensionsJson, snapshot.data_updated_at AS dataUpdatedAt FROM batch_analytics_snapshot snapshot JOIN selection_batch batch ON batch.id=snapshot.batch_id WHERE snapshot.immutable=1
AND YEAR(batch.start_at)=#{filters.academicYear}
AND batch.id=#{filters.batchId}
ORDER BY batch.start_at, batch.id LIMIT 10000
